<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { ideasApi, strategiesApi } from '../api/services'; import { ApiError } from '../api/http'; import { useAuth } from '../composables/useAuth'; import AppLoading from '../components/AppLoading.vue'; import AppNotice from '../components/AppNotice.vue'
import type { Analysis, Idea, Strategy } from '../types/api'
const { state } = useAuth(); const ideas = ref<Idea[]>([]), strategies = ref<Strategy[]>([]), loading = ref(true), error = ref(''), success = ref(''), showForm = ref(false), selected = ref<Idea | null>(null), analysis = ref<Analysis | null>(null)
const form = ref({ title: '', problem: '', proposedSolution: '', expectedBenefits: '', strategyId: '' }); const review = ref({ decision: 'APPROVED', priority: 'MEDIUM', justification: '' })
const isOperator = computed(() => state.user?.role === 'OPERATOR')
async function load() { loading.value = true; try { const [ideaPage, strategyPage] = await Promise.all([ideasApi.list(), strategiesApi.list({ active: true })]); ideas.value = ideaPage.content; strategies.value = strategyPage.content } catch (e) { error.value = e instanceof ApiError ? e.message : 'Falha ao carregar ideias.' } finally { loading.value = false } }
function newIdea() { selected.value = null; form.value = { title: '', problem: '', proposedSolution: '', expectedBenefits: '', strategyId: strategies.value[0]?.id || '' }; showForm.value = true }
function editIdea(item: Idea) { selected.value = item; form.value = { title: item.title, problem: item.problem, proposedSolution: item.proposedSolution, expectedBenefits: item.expectedBenefits, strategyId: item.strategyId }; showForm.value = true }
async function save() { try { if (selected.value) await ideasApi.update(selected.value.id, form.value); else await ideasApi.create(form.value); showForm.value = false; success.value = 'Ideia salva como rascunho.'; await load() } catch (e) { error.value = e instanceof ApiError ? e.message : 'Não foi possível salvar.' } }
async function submit(item: Idea) { try { await ideasApi.submit(item.id); success.value = 'Ideia enviada para avaliação.'; await load() } catch (e) { error.value = e instanceof ApiError ? e.message : 'Não foi possível enviar.' } }
async function remove(item: Idea) { if (!confirm(`Excluir “${item.title}”?`)) return; try { await ideasApi.delete(item.id); success.value = 'Rascunho excluído.'; await load() } catch (e) { error.value = e instanceof ApiError ? e.message : 'Não foi possível excluir.' } }
async function openReview(item: Idea) { selected.value = item; analysis.value = null; try { analysis.value = await ideasApi.analysis(item.id) } catch (e) { if (!(e instanceof ApiError && e.status === 404)) error.value = e instanceof ApiError ? e.message : '' } }
async function requestAnalysis() { if (!selected.value) return; try { analysis.value = await ideasApi.analyze(selected.value.id); success.value = 'Parecer consultivo atualizado.' } catch (e) { error.value = e instanceof ApiError && e.status === 503 ? 'Parecer consultivo indisponível no momento. A avaliação manual continua disponível.' : e instanceof ApiError ? e.message : 'Não foi possível solicitar o parecer.' } }
async function reviewIdea() { if (!selected.value) return; try { await ideasApi.review(selected.value.id, review.value); selected.value = null; success.value = 'Avaliação registrada.'; await load() } catch (e) { error.value = e instanceof ApiError ? e.message : 'Não foi possível avaliar.' } }
onMounted(load)
</script>
<template><section class="page"><div class="page-heading"><div><p class="eyebrow">INICIATIVAS</p><h1>{{ isOperator ? 'Minhas ideias' : 'Avaliação de ideias' }}</h1><p>{{ isOperator ? 'Registre propostas e acompanhe o retorno.' : 'Priorize propostas submetidas e registre a decisão.' }}</p></div><button v-if="isOperator" class="button button--primary" @click="newIdea">Nova ideia</button></div><AppNotice tone="error" :message="error"/><AppNotice tone="success" :message="success"/><AppLoading v-if="loading"/><div v-else-if="!ideas.length" class="empty"><h2>Nenhuma ideia encontrada</h2><p>{{ isOperator ? 'Crie uma ideia para começar.' : 'Ideias enviadas aparecerão aqui.' }}</p></div><div v-else class="cards"><article v-for="item in ideas" :key="item.id" class="card"><div class="card-top"><span class="badge">{{ item.status }}</span><span v-if="item.priority" class="badge badge--gold">{{ item.priority }}</span></div><h2>{{ item.title }}</h2><p>{{ item.problem }}</p><small v-if="item.reviewJustification">{{ item.reviewJustification }}</small><div class="actions"><button v-if="isOperator && item.status === 'DRAFT'" class="text-button" @click="editIdea(item)">Editar</button><button v-if="isOperator && item.status === 'DRAFT'" class="text-button" @click="submit(item)">Enviar</button><button v-if="isOperator && item.status === 'DRAFT'" class="text-button text-button--danger" @click="remove(item)">Excluir</button><button v-if="!isOperator" class="text-button" @click="openReview(item)">Consultar e avaliar</button></div></article></div><div v-if="showForm" class="modal"><form class="dialog" @submit.prevent="save"><h2>{{ selected ? 'Editar ideia' : 'Nova ideia' }}</h2><label>Título<input v-model="form.title" required></label><label>Problema<textarea v-model="form.problem" required></textarea></label><label>Solução proposta<textarea v-model="form.proposedSolution" required></textarea></label><label>Benefícios esperados<textarea v-model="form.expectedBenefits" required></textarea></label><label>Estratégia<select v-model="form.strategyId" required><option v-for="strategy in strategies" :key="strategy.id" :value="strategy.id">{{ strategy.title }}</option></select></label><div class="dialog-actions"><button type="button" class="button" @click="showForm = false">Cancelar</button><button class="button button--primary">Salvar rascunho</button></div></form></div><div v-if="selected && !showForm && !isOperator" class="modal"><section class="dialog dialog--wide"><h2>Avaliar ideia</h2><p class="muted">{{ selected.title }}</p><AppNotice tone="error" :message="error"/><section class="analysis"><div class="section-heading"><h3>Parecer consultivo</h3><button class="button" @click="requestAnalysis">Solicitar parecer</button></div><template v-if="analysis"><p><strong>Resumo:</strong> {{ analysis.summary }}</p><p><strong>Alinhamento:</strong> {{ analysis.strategicAlignment }}</p><p><strong>Benefícios:</strong> {{ analysis.potentialBenefits }}</p><p><strong>Riscos:</strong> {{ analysis.risks }}</p><p><strong>Informações pendentes:</strong> {{ analysis.missingInformation }}</p><p><strong>Recomendação:</strong> {{ analysis.recommendation }}</p></template><p v-else class="muted">Ainda não há parecer disponível para esta ideia.</p></section><form @submit.prevent="reviewIdea"><div class="form-grid"><label>Decisão<select v-model="review.decision"><option value="APPROVED">Aprovar</option><option value="REJECTED">Rejeitar</option></select></label><label>Prioridade<select v-model="review.priority"><option value="LOW">Baixa</option><option value="MEDIUM">Média</option><option value="HIGH">Alta</option><option value="CRITICAL">Crítica</option></select></label></div><label>Justificativa<textarea v-model="review.justification" required></textarea></label><div class="dialog-actions"><button type="button" class="button" @click="selected = null">Cancelar</button><button class="button button--primary">Registrar avaliação</button></div></form></section></div></section></template>
